import 'dart:io';import 'dart:ui' as ui;import 'package:flutter/material.dart';import 'package:flutter/rendering.dart';import 'package:flutter/services.dart';import 'package:flutter_test/flutter_test.dart';import '../candidate15/home_candidate_15.dart';
Future<void> render(WidgetTester t,Brightness b,String n)async{t.view.physicalSize=const Size(390,844);t.view.devicePixelRatio=1;addTearDown(t.view.resetPhysicalSize);addTearDown(t.view.resetDevicePixelRatio);final k=GlobalKey();await t.pumpWidget(MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,brightness:b,fontFamily:'C15Roboto'),home:RepaintBoundary(key:k,child:const Candidate15Home())));await t.pump();await t.pump(const Duration(milliseconds:100));expect(t.takeException(),isNull);final bd=k.currentContext!.findRenderObject()! as RenderRepaintBoundary;final bytes=await t.runAsync(()async{final im=await bd.toImage(pixelRatio:1);final d=await im.toByteData(format:ui.ImageByteFormat.png);final o=d!.buffer.asUint8List();im.dispose();return o;});final file=File('candidate15/rendered/$n.png');await t.runAsync(()async{await file.parent.create(recursive:true);await file.writeAsBytes(bytes!);});}
void main(){setUpAll(()async{final l=FontLoader('C15Roboto')..addFont(rootBundle.load('candidate15/fonts/Roboto.ttf'));await l.load();});testWidgets('light',(t)async=>render(t,Brightness.light,'candidate15-light-390x844'));testWidgets('dark',(t)async=>render(t,Brightness.dark,'candidate15-dark-390x844'));}